sql.where:
dc.deleted = 0
AND dc.code = #{req.code}
AND dc.name LIKE CONCAT('%', #{req.name}, '%')
AND dc.level = #{req.level}

    AND EXISTS (SELECT 1 FROM mdm_defect_code_op dco
                WHERE dco.defect_code_id = dc.id AND dco.op_id = #{req.opId} AND dco.deleted = 0)


    AND EXISTS (SELECT 1 FROM mdm_defect_code_mat_cat dcmc
                WHERE dcmc.defect_code_id = dc.id AND dcmc.mat_cat_id = #{req.matCatId}
                  AND dcmc.deleted = 0)

AND dc.parent_id = #{req.parentId}
AND dc.status = #{req.status}

    AND dc.create_time BETWEEN #{req.createTime[0]} AND #{req.createTime[1]}
